function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'blue' | 'green' | 'amber' | 'red' | 'neutral' }) {
  const tones = {
    blue: 'bg-[#e3f3f7] text-[#167085]',
    green: 'bg-[#e2f4ed] text-[#247354]',
    amber: 'bg-[#fff2d9] text-[#996419]',
    red: 'bg-[#fce4e2] text-[#a13e3e]',
    neutral: 'bg-slate-100 text-slate-600',
  };
  return <span className={`inline-flex items-center gap-1 rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-[.12em] ${tones[tone]}`}>{children}</span>;
}

function Button({ children, variant = 'primary', className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'ghost' }) {
  const styles = {
    primary: 'bg-[#15527a] text-white shadow-sm hover:bg-[#0e4569]',
    secondary: 'border border-slate-200 bg-white text-[#1e5272] hover:border-[#62b7c7] hover:bg-[#f3fbfc]',
    ghost: 'text-slate-500 hover:bg-slate-100 hover:text-[#15527a]',
  };
  return <button className={`inline-flex min-h-9 items-center justify-center gap-2 rounded-lg px-3.5 text-xs font-bold transition-colors ${styles[variant]} ${className}`} {...props}>{children}</button>;
}

function SectionTitle({ title, subtitle, action }: { title: string; subtitle?: string; action?: ReactNode }) {
  return <div className="mb-4 flex items-end justify-between gap-3">
    <div><h2 className="text-[15px] font-extrabold tracking-[-.02em] text-[#183d5b]">{title}</h2>{subtitle && <p className="mt-1 text-xs text-slate-500">{subtitle}</p>}</div>
    {action}
  </div>;
}

function KpiCard({ label, value, detail, trend, tone = 'blue', icon: Icon }: { label: string; value: string; detail: string; trend?: 'up' | 'down'; tone?: 'blue' | 'green' | 'amber' | 'red'; icon: typeof Gauge }) {
  const color = { blue: 'text-[#267f9a] bg-[#e7f5f8]', green: 'text-[#28805c] bg-[#e7f5ec]', amber: 'text-[#aa741d] bg-[#fff3d9]', red: 'text-[#b34d48] bg-[#fce9e8]' }[tone];
  return <div data-testid={`card-kpi-${label.toLowerCase().replaceAll(' ', '-')}`} className="card-shadow rounded-xl border border-slate-200 bg-white p-4">
    <div className="flex items-start justify-between"><p className="text-[10px] font-extrabold uppercase tracking-[.13em] text-slate-500">{label}</p><span className={`rounded-lg p-2 ${color}`}><Icon size={15} /></span></div>
    <div className="mt-3 flex items-baseline gap-2"><strong className="font-mono text-[26px] font-medium tracking-[-.06em] text-[#183d5b]">{value}</strong>{trend && <span className={`flex items-center text-[11px] font-bold ${trend === 'up' ? 'text-emerald-600' : 'text-rose-600'}`}>{trend === 'up' ? <TrendingUp size={12} /> : <TrendingDown size={12} />} {trend === 'up' ? '+4.2%' : '-1.1%'}</span>}</div>
    <p className="mt-1 text-[11px] text-slate-500">{detail}</p>
  </div>;
}

function ChartCard({ compact = false }: { compact?: boolean }) {
  return <div data-testid="chart-freight-market" className="card-shadow rounded-xl border border-slate-200 bg-white p-4">
    <div className="mb-4 flex items-start justify-between gap-3"><div><h3 className="text-[15px] font-extrabold text-[#183d5b]">Newcastle → Paradip</h3><p className="mt-1 text-xs text-slate-500">Capesize freight · USD / metric tonne</p></div><div className="flex items-center gap-3 text-[10px] font-semibold text-slate-500"><span className="flex items-center gap-1"><i className="h-2 w-2 rounded-full bg-[#237e9d]" />Actual</span><span className="flex items-center gap-1"><i className="h-2 w-2 rounded-full bg-[#e4a738]" />Forecast</span><Badge tone="green">78% confidence</Badge></div></div>
    <div className={compact ? 'h-[190px]' : 'h-[260px]'}><ResponsiveContainer width="100%" height="100%"><ComposedChart data={marketSeries} margin={{ top: 4, right: 5, left: -17, bottom: 0 }}>
      <defs><linearGradient id="areaBand" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#7dcbd3" stopOpacity=".28" /><stop offset="100%" stopColor="#7dcbd3" stopOpacity=".02" /></linearGradient></defs>
      <CartesianGrid vertical={false} stroke="#e9eef2" /><XAxis dataKey="date" tick={{ fontSize: 10, fill: '#8495a2' }} axisLine={false} tickLine={false} /><YAxis tick={{ fontSize: 10, fill: '#8495a2' }} axisLine={false} tickLine={false} tickFormatter={(v) => `$${v}`} domain={['dataMin - 2', 'dataMax + 2']} /><ChartTooltip contentStyle={{ borderRadius: 8, border: '1px solid #dce8ed', fontSize: 11 }} formatter={(v: number, name: string) => [`$${v?.toFixed(2)}`, name]} />
      <Area dataKey="high" stroke="none" fill="url(#areaBand)" /><Area dataKey="low" stroke="none" fill="white" fillOpacity=".8" />
      <Line dataKey="actual" stroke="#237e9d" strokeWidth={2.5} dot={{ r: 2.5, fill: '#237e9d' }} connectNulls={false} /><Line dataKey="forecast" stroke="#e4a738" strokeWidth={2.5} strokeDasharray="5 4" dot={{ r: 2.5, fill: '#e4a738' }} connectNulls={false} />
    </ComposedChart></ResponsiveContainer></div>
  </div>;
}

function Sidebar({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [location] = useLocation();
  return <><div onClick={onClose} className={`fixed inset-0 z-30 bg-[#06233a]/45 transition-opacity md:hidden ${open ? 'opacity-100' : 'pointer-events-none opacity-0'}`} />
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[264px] flex-col bg-[#0d2942] text-slate-300 transition-transform md:static md:z-0 md:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="nav-grid absolute inset-0 opacity-60" /><div className="relative flex h-full flex-col">
        <div className="flex h-[78px] items-center justify-between border-b border-[#28445a] px-5"><Link data-testid="link-brand" href="/dashboard" className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#54c2d1] text-[#082a42] shadow-[0_0_0_4px_rgba(84,194,209,.12)]"><Anchor size={19} strokeWidth={2.5} /></span><span><b className="block text-[15px] tracking-[-.04em] text-white">Freight<span className="text-[#65d0d3]">IQ</span></b><small className="text-[9px] font-bold uppercase tracking-[.22em] text-slate-400">Charter intelligence</small></span></Link><button data-testid="button-close-sidebar" aria-label="Close navigation" onClick={onClose} className="rounded p-1 text-slate-400 hover:text-white md:hidden"><X size={18} /></button></div>
        <div className="px-4 pt-5"><div className="mb-3 px-2 text-[9px] font-bold uppercase tracking-[.18em] text-slate-500">Workspace</div>{navItems.slice(0, 2).map((item) => <NavItem item={item} active={location === item.href} key={item.href} />)}</div>
        <div className="px-4 pt-5"><div className="mb-3 px-2 text-[9px] font-bold uppercase tracking-[.18em] text-slate-500">Intelligence</div>{navItems.slice(2, 5).map((item) => <NavItem item={item} active={location === item.href} key={item.href} />)}</div>
        <div className="px-4 pt-5"><div className="mb-3 px-2 text-[9px] font-bold uppercase tracking-[.18em] text-slate-500">Optimization</div>{navItems.slice(5).map((item) => <NavItem item={item} active={location === item.href} key={item.href} />)}</div>
        <div className="mt-auto border-t border-[#28445a] p-4"><div className="mb-3 rounded-lg border border-[#2f5368] bg-[#153852] p-3"><div className="flex items-center gap-2 text-[11px] font-bold text-[#94e3e1]"><Sparkles size={13} /> Model health</div><div className="mt-2 flex items-end justify-between"><span className="text-[10px] text-slate-400">Last trained 2h ago</span><span className="font-mono text-[11px] text-white">98.6%</span></div><div className="mt-2 h-1 rounded-full bg-[#31566d]"><div className="h-1 w-[86%] rounded-full bg-[#54c2d1]" /></div></div><div className="flex items-center gap-3"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#d6edf0] text-xs font-extrabold text-[#15527a]">AS</span><div className="min-w-0"><p className="truncate text-xs font-bold text-white">Alex Sullivan</p><p className="truncate text-[10px] text-slate-500">Chartering manager</p></div><MoreHorizontal size={15} className="ml-auto text-slate-500" /></div></div>
      </div>
    </aside></>;
}

